--
-- Table structure for table `STUDY_SESSIONS`
--

DROP TABLE IF EXISTS `STUDY_SESSIONS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `STUDY_SESSIONS` (
  `SessionID` int NOT NULL AUTO_INCREMENT,
  `StudentID` int DEFAULT NULL,
  `SubjectID` int DEFAULT NULL,
  `StartTime` time DEFAULT NULL,
  `EndTime` time DEFAULT NULL,
  `SessionDate` date DEFAULT NULL,
  `FocusLevel` int DEFAULT NULL,
  `SessionNote` text,
  PRIMARY KEY (`SessionID`),
  KEY `StudentID` (`StudentID`),
  KEY `SubjectID` (`SubjectID`),
  CONSTRAINT `study_sessions_ibfk_1` FOREIGN KEY (`StudentID`) REFERENCES `STUDENT` (`StudentID`) ON DELETE CASCADE,
  CONSTRAINT `study_sessions_ibfk_2` FOREIGN KEY (`SubjectID`) REFERENCES `SUBJECT` (`SubjectID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1418 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

